python3 - <<'PY'
from itertools import product
D=list(range(-2,3))
vals=list(range(-5,10))
squares={i*i for i in range(20)}
sol=[]
for tup in product(vals, repeat=len(D)):
    f=dict(zip(D,tup))
    ok=True
    for a in D:
        if 2*a not in f: continue
        for x in D:
            E=f[x]+(f[a]-x)*f[2*a]
            if E not in squares:
                ok=False; break
        if not ok: break
    if ok:
        sol.append(tup)
        if len(sol)>20: break
print(len(sol))
for tup in sol[:20]: print(dict(zip(D,tup)))
